+            viewBox: "0 0 14 14",
+            fill: "none",
+            strokeWidth: "2",
+            strokeLinecap: "round",
+          },
+          React.createElement("line", { x1: "7", y1: "1", x2: "7", y2: "13" }),
+          React.createElement("line", { x1: "1", y1: "7", x2: "13", y2: "7" })
+        )
+      )
+    ),
+    React.createElement(
+      "div",
+      { className: "details", id, role: "region" },
+      React.createElement(
+        "div",
+        { className: "details-inner" },
+        React.createElement(
+          "div",
+          { className: "details-body" },
+          hasBullets
+            ? answer.split("\n").reduce(
+                (acc, line) => {
+                  if (line.startsWith("- ") || line.startsWith("•")) {
+                    if (!acc.inList) {
+                      acc.elements.push(
+                        React.createElement("ul", { key: `ul-${acc.elements.length}` },
+                          React.createElement("li", { key: line }, line.replace(/^[-•]\s*/, ""))
+                        )
+                      );
+                      acc.inList = true;
+                    } else {
+                      const lastUl = acc.elements[acc.elements.length - 1];
+                      acc.elements[acc.elements.length - 1] = React.cloneElement(
+                        lastUl,
+                        null,
+                        ...lastUl.props.children,
+                        React.createElement("li", { key: line }, line.replace(/^[-•]\s*/, ""))
+                      );
+                    }
+                  } else if (line.trim()) {
+                    acc.inList = false;
+                    acc.elements.push(React.createElement("p", { key: line }, line));
+                  }
+                  return acc;
+                },
+                { elements: [], inList: false }
+              ).elements
+            : React.createElement("p", null, answer)
+        )
+      )
+    )
+  );
+}
