+function FaqPage() {
+  return React.createElement(
+    React.Fragment,
+    null,
+    React.createElement(
+      "header",
+      { className: "page-header" },
+      React.createElement(
+        "div",
+        { className: "badge" },
+        React.createElement("span", null, "🐱"),
+        "Cat Care Guide"
+      ),
+      React.createElement("h1", null, "Frequently Asked Questions"),
+      React.createElement(
+        "p",
+        null,
+        "Everything you need to know about living with and caring for your feline companion."
+      )
+    ),
+    React.createElement(
+      "main",
+      { className: "faq-container" },
